Valuation_Source.inputs:
@if(
  contains(
    parameters('UCH-AVP Parameter (Valid CoStar Codes) (clr_UCHAVPParameterValidPropertyCodes)'),
    body('Update_Payload')?['PropertyType']
  ),
  'CoStar',
  if(
    contains(
      parameters('UCH-AVP Parameter (Valid Zillow Codes) (clr_UCHAVPParameterValidZillowCodes)'),
      body('Update_Payload')?['PropertyType']
    ),
    'Zillow',
    null
  )
)

content.OwnerZipFive:
@if(
  not(empty(string(triggerBody()?['OwnerZipFive']))), 
  if(
    greater(
      length(string(triggerBody()?['OwnerZipFive'])),
      5
    ),
    substring(
      string(triggerBody()?['OwnerZipFive']),
      0,
      5
    ),
    triggerBody()?['OwnerZipFive']
  ), 
  null
)

inputs.value:
@if(
  and(
    not(empty(string(body('Update_Payload')?['SaleAmount']))),
    not(empty(string(body('Existing_Dataset')?['SaleAmount'])))
  ),
  lessOrEquals(
    div(
      body('Update_Payload')?['SaleAmount'],
      body('Existing_Dataset')?['SaleAmount']
    ),
    0.9
  ),
  if(
    and(
      not(empty(string(body('Update_Payload')?['FinalJudgementAmount']))),
      not(empty(string(body('Existing_Dataset')?['FinalJudgementAmount'])))
    ),
    lessOrEquals(
      div(
        body('Update_Payload')?['FinalJudgementAmount'],
        body('Existing_Dataset')?['FinalJudgementAmount']
      ),
      0.9
    ),
    if(
      and(
        not(empty(string(body('Update_Payload')?['FirstLoanAmount']))),
        not(empty(string(body('Existing_Dataset')?['FirstLoanAmount'])))
      ),
      lessOrEquals(
        div(
          body('Update_Payload')?['FirstLoanAmount'],
          body('Existing_Dataset')?['FirstLoanAmount']
        ),
        0.9
      ),
      false
    )
  )
)

Valuation_Issue.inputs:
@if(
  or(
    or(
      empty(trim(string(body('Update_Payload')?['Address']))),
      contains(
        toLower(string(body('Update_Payload')?['Address'])),
        'unknown'
      ),
      contains(
        toLower(string(body('Update_Payload')?['Address'])),
        'available'
      ),
      and(
        and(
          not(
            equals(
              body('Update_Payload')?['PropertyType'],
              'LND'
            )
          ),
          not(
            equals(
              body('Update_Payload')?['PropertyType'],
              'AGR'
            )
          )
        ),
        not(
          startsWith(
            string(body('Update_Payload')?['Address']),
            '1'
          )
        ),
        not(
          startsWith(
            string(body('Update_Payload')?['Address']),
            '2'
          )
        ),
        not(
          startsWith(
            string(body('Update_Payload')?['Address']),
            '3'
          )
        ),
        not(
          startsWith(
            string(body('Update_Payload')?['Address']),
            '4'
          )
        ),
        not(
          startsWith(
            string(body('Update_Payload')?['Address']),
            '5'
          )
        ),
        not(
          startsWith(
            string(body('Update_Payload')?['Address']),
            '6'
          )
        ),
        not(
          startsWith(
            string(body('Update_Payload')?['Address']),
            '7'
          )
        ),
        not(
          startsWith(
            string(body('Update_Payload')?['Address']),
            '8'
          )
        ),
        not(
          startsWith(
            string(body('Update_Payload')?['Address']),
            '9'
          )
        )
      )
    ),
    or(
      empty(trim(string(body('Update_Payload')?['County']))),
      contains(
        toLower(string(body('Update_Payload')?['County'])),
        'unknown'
      ),
      contains(
        toLower(string(body('Update_Payload')?['County'])),
        'available'
      )
    ),
    or(
      empty(trim(string(body('Update_Payload')?['City']))),
      contains(
        toLower(string(body('Update_Payload')?['City'])),
        'unknown'
      ),
      contains(
        toLower(string(body('Update_Payload')?['City'])),
        'available'
      )
    ),
    or(
      empty(trim(string(body('Update_Payload')?['State']))),
      contains(
        toLower(string(body('Update_Payload')?['State'])),
        'unknown'
      ),
      contains(
        toLower(string(body('Update_Payload')?['State'])),
        'available'
      )
    ),
    or(
      empty(trim(string(body('Update_Payload')?['Zip']))),
      contains(
        toLower(string(body('Update_Payload')?['Zip'])),
        'unknown'
      ),
      contains(
        toLower(string(body('Update_Payload')?['Zip'])),
        'available'
      )
    )
  ),
  'Incomplete Address',
  null
)

